// generated by scripts/design/gen-tokens.mjs from design/tokens.json, do not edit.
//
// Colour themes (design/DECISIONS.md): one ThemePalette per theme and mode. Pick the palette with
// ThirteenTheme.palette(dark = isSystemInDarkTheme()) or the pinned mode. An always-dark theme
// (isAlwaysDark) has one palette for both and wants darkTheme = true: use isDark(dark) for that
// flag.

package com.haugas.thirteen.ui.theme

import androidx.compose.runtime.Immutable
import androidx.compose.ui.graphics.Color

/** How Settings groups the themes: the ones that follow light and dark first, then the always-dark ones. */
public enum class ThemeGroup(
    /** The heading shown in Settings. */
    public val displayName: String,
    /** One line describing the group; for [Dark], the note beside the disabled appearance control. */
    public val summary: String,
) {
    /** Light and dark: Follows the system, or the Appearance setting. */
    Adaptive("Light and dark", "Follows the system, or the Appearance setting."),
    /** Dark: Always dark, whatever the system or the Appearance setting. */
    Dark("Dark", "Always dark, whatever the system or the Appearance setting.");

    /** The themes in this group, in the order Settings lists them. */
    public val themes: List<ThirteenTheme> get() = ThirteenTheme.ordered.filter { it.group == this }
}

/** A colour theme, chosen in Settings. Independent of light and dark, except for the always-dark themes. */
public enum class ThirteenTheme(
    /** Stable id, stored in settings and shared with the other platforms. */
    public val id: String,
    /** The name shown in Settings. */
    public val displayName: String,
    /** One line describing the theme. */
    public val summary: String,
    /** The group Settings lists the theme in. */
    public val group: ThemeGroup,
    /** Light-mode colours (the dark palette for an always-dark theme). */
    public val light: ThemePalette,
    /** Dark-mode colours. */
    public val dark: ThemePalette,
) {
    Almanac("almanac", "Almanac", "Warm paper and iron-gall ink with a signal orange accent.", ThemeGroup.Adaptive, AlmanacLight, AlmanacDark),
    Graphite("graphite", "Graphite", "Neutral greys with an electric blue accent.", ThemeGroup.Adaptive, GraphiteLight, GraphiteDark),
    Slate("slate", "Slate", "Cool slate paper with a terracotta accent.", ThemeGroup.Adaptive, SlateLight, SlateDark),
    Forest("forest", "Forest", "Bone paper and deep green ink with an amber accent.", ThemeGroup.Adaptive, ForestLight, ForestDark),
    Mono("mono", "Mono", "Black and white only, with a quiet blue grey for the Gregorian side.", ThemeGroup.Adaptive, MonoLight, MonoDark),
    Obsidian("obsidian", "Obsidian", "Near black for OLED screens, warm ink and the signal orange. Always dark.", ThemeGroup.Dark, ObsidianDark, ObsidianDark),
    Midnight("midnight", "Midnight", "Deep navy with a teal accent and periwinkle for the Gregorian side. Always dark.", ThemeGroup.Dark, MidnightDark, MidnightDark),
    Phosphor("phosphor", "Phosphor", "Green black like an old terminal, phosphor green and amber. Always dark.", ThemeGroup.Dark, PhosphorDark, PhosphorDark);

    /** True for a theme that is always dark: darkTheme = true whatever the system or the pinned mode. */
    public val isAlwaysDark: Boolean get() = group == ThemeGroup.Dark

    /** Whether to draw dark: [dark] (the system or the pinned mode), or always for an always-dark theme. */
    public fun isDark(dark: Boolean): Boolean = dark || isAlwaysDark

    /** The palette for light or dark mode (always the dark one for an always-dark theme). */
    public fun palette(dark: Boolean): ThemePalette = if (isDark(dark)) this.dark else light

    public companion object {
        /** The theme for new users. */
        public val Default: ThirteenTheme = Almanac

        /** Every theme, in the order Settings lists them. */
        public val ordered: List<ThirteenTheme> = entries.toList()

        /** The theme with this [id], or [Default] for null or unknown ids. */
        public fun fromId(id: String?): ThirteenTheme = entries.firstOrNull { it.id == id } ?: Default
    }
}

/** The colour roles of one theme in one mode (design/tokens.json "roles"). */
@Immutable
public data class ThemePalette(
    /** Page background. */
    public val paper: Color,
    /** Cards, popovers and raised surfaces. */
    public val paperRaised: Color,
    /** Wells, grid cells and inset surfaces. */
    public val paperSunk: Color,
    /** Primary text (12:1 or more on every paper). */
    public val ink: Color,
    /** Secondary text (7:1 or more on every paper). */
    public val inkSecondary: Color,
    /** Tertiary text and captions (4.5:1 or more on every paper). */
    public val inkTertiary: Color,
    /** Hairlines and card strokes. */
    public val rule: Color,
    /** Faint dividers inside a surface. */
    public val ruleSoft: Color,
    /** Emphasised rules: the almanac's heavy lines. */
    public val ruleStrong: Color,
    /** The theme's signal colour for fills and marks: today, progress, selection. Not for body text. */
    public val accent: Color,
    /** Accent for text and icons on paper and on accent-wash (4.5:1 or more). */
    public val accentText: Color,
    /** Soft opaque accent fill behind accent text. */
    public val accentWash: Color,
    /** Translucent accent tint for hover and selected backgrounds. */
    public val accentSoft: Color,
    /** Text and glyphs on a solid accent fill. */
    public val onAccent: Color,
    /** Tint of system controls (Apple .tint, Android and Windows control accents). Light: 4.5:1 or more on paper. Dark: 4.5:1 or more on every paper, and white text on it 3:1 or more. */
    public val controlTint: Color,
    /** The Gregorian foil: everything 12-month, in a colour clearly apart from the accent. */
    public val foil: Color,
    /** Soft opaque foil fill behind foil text. */
    public val foilWash: Color,
    /** Translucent foil tint. */
    public val foilSoft: Color,
    /** Text and glyphs on a solid foil fill. */
    public val onFoil: Color,
    /** Keyboard focus ring (3:1 or more against paper). */
    public val focus: Color,
    /** Translucent overlay behind sheets and dialogs. */
    public val scrim: Color,
    /** Tint of the paper grain texture (web). */
    public val grain: Color,
    /** Colour of drop shadows (alpha comes from "shadows"). */
    public val shadow: Color,
)

